class Zwierze {
  constructor(imie) {
    this.imie = imie;
  }

  wydajDzwiek() {
    return `${this.imie} wydaje jakis dzwiek`;
  }
}

class Pies extends Zwierze {
  constructor(imie, rasa) {
    super(imie); // MUSI byc wywolane PRZED uzyciem this w konstruktorze
    this.rasa = rasa;
  }
}

class Pies extends Zwierze {
  constructor(imie, rasa) {
    super(imie);
    this.rasa = rasa;
  }

  wydajDzwiek() {
    return `${this.imie} (${this.rasa}) szczeka: Hau!`;
  }
}

const reksio = new Pies("Reksio", "Owczarek");
console.log(reksio.wydajDzwiek()); // "Reksio (Owczarek) szczeka: Hau!" - WERSJA z Pies

class Pies extends Zwierze {
  constructor(imie, rasa) {
    super(imie);
    this.rasa = rasa;
  }

  wydajDzwiek() {
