class Pracownik2 {
  constructor(imie, pensja) {
    this.imie = imie;
    this.pensja = pensja;
  }
  opis() {
    return `${this.imie}, pensja: ${this.pensja}`;
  }
}

class Kierownik extends Pracownik2 {
  constructor(imie, pensja, zespol) {
    super(imie, pensja);
    this.zespol = zespol;
  }
  opis() {
    return super.opis() + `, kierownik zespolu (${this.zespol.length} osob)`;
  }
}

const kierownik = new Kierownik("Anna", 9000, ["Tomek", "Kasia", "Piotr"]);
console.log(kierownik.opis());
// "Anna, pensja: 9000, kierownik zespolu (3 osob)"

class Ksztalt3 {
  obwod() {
    return 0;
  }
}

class Kwadrat extends Ksztalt3 {
  constructor(bok) {
    super();
    this.bok = bok;
  }
  obwod() {
    return 4 * this.bok;
  }
}

class Szescian extends Kwadrat {
  objetosc() {
    return this.bok ** 3;
  }
}

const szescian = new Szescian(3);
console.log(szescian.obwod());   // 12 - odziedziczone z Kwadrat
console.log(szescian.objetosc()); // 27
console.log(szescian instanceof Ksztalt3); // true - lancuch dziedziczenia

class Konto2 {
  constructor(saldo) {
    this.saldo = saldo;
  }
  wyciag() {
    return `Saldo: ${this.saldo}`;
  }
}

class KontoOszczednosciowe extends Konto2 {
  constructor(saldo, oprocentowanie) {
    super(saldo);
    this.oprocentowanie = oprocentowanie;
  }
  wyciag() {
    return super.wyciag() + `, oprocentowanie: ${this.oprocentowanie}%`;
  }
}

const konto = new KontoOszczednosciowe(1000, 3.5);
console.log(konto.wyciag()); // "Saldo: 1000, oprocentowanie: 3.5%"

class Rodzic {
  constructor(x) {
    this.x = x;
  }
}

class Dziecko extends Rodzic {
  constructor(x, y) {
    // this.y = y; -- BLAD: must call super constructor before accessing 'this'
    super(x); // POPRAWNIE - musi byc PIERWSZE
    this.y = y; // teraz bezpieczne
  }
}

// this (nowo tworzona instancja) nie jest w pelni "gotowe", dopoki czesc
// pochodzaca od rodzica (pola ustawiane przez constructor klasy bazowej)
// nie zostanie zainicjalizowana przez super(). JavaScript wymusza te
// kolejnosc, rzucajac blad przy kazdej probie uzycia this przed super()
// w konstruktorze klasy, ktora dziedziczy po innej (extends).
